pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 amount, address receiver2) internal {
        vm.assume(amount > 0);
        vm.assume(receiver2 != address(0));
        bool reverted1;
        bool reverted2;
        try c.sendTo(address(this), amount) { reverted1 = false; } catch { reverted1 = true; }
        try c.sendTo(receiver2, amount) { reverted2 = false; } catch { reverted2 = true; }
        assertTrue(reverted1 == reverted2);
    }

    function testFuzz_run(uint256 amount, address receiver2) public {
        vm.assume(receiver2.code.length == 0 && uint160(receiver2) > 0xffff && receiver2 != address(this) && receiver2 != address(c) && receiver2 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && receiver2 != 0x000000000000000000636F6e736F6c652e6c6f67 && receiver2 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && receiver2 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, receiver2);
    }

    receive() external payable {}
}
